void executeLine(char *line, unsigned int length) {
    /* Implement execution logic here. */
    //skip leading spaces
    unsigned int head = 0;
    while ( head < length && line[head] == ' ') {
        ++head;
    }

    //base cases
    if (head == length) {
        return; 
    }

    unsigned int tail = head;
    //trying to find end of first work aka the command , and since we figured out leading spaces we jsut check til we reach another empty space.
    while (tail < length && line[tail] != ' ') {
        ++tail;
    }

    //check if its echo
    if (tail - head == 4&&
        line[head] == 'e'&&
        line[head + 1] == 'c'&&
        line[head + 2] == 'h'&&
        line[head + 3] == 'o'
    ) {
        //we know we have echo cmd, just gotta figure out what to echo
        //gotta skip spaces after cmd
        unsigned int echoStart = tail;
        while (echoStart < length && line[echoStart] == ' ') {
            ++echoStart;
        }

        ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, &line[echoStart], (int)(length - echoStart));
        ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "\n", 1);
        return;

        // if (echoStart < length) {
        //     //print the rest of the line as the echo content
        //     printf("%s\n", &line[echoStart]);
        // }
    }
    //if its not echo
    else {
        // int notFoundStart = tail;
        // while (notFoundStart < length && line[notFoundStart] == ' ') {
        //     notFoundStart++;
        // }

        // if (notFoundStart < length) {
        //     //print the rest of the line as the echo content
        //     for (int i = notFoundStart; i < length; i++) {
        //         int word = notFoundStart[i];
        //         notFoundStart++;
        //     }
        // }
        line[tail] = '\0';
        ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "command not found: ", 19);
        ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, &line[head], (int)(tail - head));
        ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "\n", 1);
    }
}
void mshStart(void) {
    char line[21];             /* 20 bytes plus the terminating '\0' */
    unsigned int length = 0;
    unsigned int excess = 0;


    ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "msh> ", 5);

    for (;;) {
        char value;
        int count = ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_READ, &value, 1);

        if (count <= 0) {
            continue;
        }

        // if (value == UART_INPUT_LOST) {
        //     length = 0U;
        //     excess = 0U;
        //     line[0] = '\0';
        //     /* Reset any overlong-line state you add later. */
        //     ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "\ninput lost; line discarded\nmsh> ", 32U);
        //     continue;
        // }

        if (value == '\n') {
            line[length] = '\0';

            // if (excess != 0U) {
            //     ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "too long\n", 9);
            // } else {
            //     executeLine(line, length);
            // }
            if (excess == 0) {
                executeLine(line, length);
            }

            length = 0U;
            excess = 0U;
            ioctl(MINEMU_FD_UART0, MINEMU_OP_UART_WRITE, "msh> ", 5);
            continue;
        }

        //backspace
        if (value == 0x08 || value == 0x7F) {
            if (excess != 0) {
                --excess;
            } else if (length != 0) {
                --length;
                line[length] = '\0';
            }
            continue;
        }

        //if lines over 20 bytes

        if (length < 20) {
            line[length] = (char)value;
            length++;
        } else {
            excess++;
        }
    }
}